css:
.si * {
    font-family: Calibri, Arial, sans-serif;
    font-size: 11px;
    color: #333;
    line-height: 1.4;
}
.si table { width: 100%; }
.si .bt { border-collapse: separate; border-spacing: 0; }
.si .bt td, .si .bt th {
    border-right: 1px solid #aaa;
    border-bottom: 1px solid #aaa;
    padding: 4px 6px;
    vertical-align: top;
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
}
.si .bt td:first-child, .si .bt th:first-child { border-left: 1px solid #aaa; }
.si .bt thead th {
    border-top: 1px solid #aaa;
    background: #f0f0f0;
    font-weight: bold;
    font-size: 11px;
}
.si .bt tbody tr:first-child td { border-top: 1px solid #aaa; }
.si .bt thead { display: table-header-group; }
.si .bt tbody { display: table-row-group; }
.si .bt tr { page-break-inside: auto; break-inside: auto; }
.si .bt td {
    page-break-inside: auto; break-inside: auto;
    overflow-wrap: break-word; word-wrap: break-word;
}

/* Description cell — the key to zero phantom gaps from rich-text descriptions:
   render every nested <p>, <div>, <span> as INLINE. The trailing <p><br></p>
   that the editor emits then collapses into the text flow instead of occupying
   a full block line. */
.si .desc-cell {
    overflow-wrap: break-word;
    word-wrap: break-word;
    word-break: break-word;
    max-width: 0;
}
.si .desc-cell p,
.si .desc-cell div,
.si .desc-cell span {
    margin: 0 !important;
    padding: 0 !important;
    display: inline;
}
.si .desc-cell img { max-width: 100%; height: auto; }
.si .desc-cell .meta-line {
    display: block;
    font-size: 9px;
    color: #666;
    margin-top: 1px;
}

.si .r { text-align: right; }
.si .c { text-align: center; }
.si .b { font-weight: bold; }

.si .doc-title {
    text-align: center;
    font-size: 18px;
    font-weight: bold;
    color: #2c3e50;
    margin: 1px 0 2px;
    letter-spacing: 3px;
}

.si .stitle {
    font-size: 12px;
    font-weight: bold;
    color: #2c3e50;
    margin: 10px 0 4px;
    border-bottom: 1px solid #2c3e50;
    padding-bottom: 2px;
}

.si .meta { margin-bottom: 10px; }
.si .meta td { border: none; padding: 4px 0; vertical-align: top; }

.si .totals {
    width: 45%; margin-left: auto;
    page-break-inside: avoid; break-inside: avoid;
}
.si .totals td { padding: 3px 6px; border: none; }
.si .gt td {
    border-top: 2px solid #2c3e50;
    font-weight: bold; font-size: 13px; padding-top: 4px;
}

.si .iw { font-size: 10px; font-style: italic; margin-top: 6px; color: #555; }

.si .info-table { page-break-inside: avoid; break-inside: avoid; }

.si .company-header {
    border-bottom: 2px solid #2c3e50;
    padding-bottom: 8px;
    margin-bottom: 10px;
}
.si .company-header td { border: none; padding: 2px 0; }
.si .company-name { font-size: 18px; font-weight: bold; color: #2c3e50; }
.si .company-detail { font-size: 10px; color: #555; line-height: 1.5; }

.nn{
    font-size: 14px; font-weight: bold; color: #2c3e50;
}


